import { chromium } from 'playwright'
import fs from 'fs'
const OUT = 'D:\\repository\\苏州市房地产监测V3'
const BASE='http://58.210.252.230:9002'
const USER='zsbase', PASS='ZS001Aa!'

const readAnswer = async () => {
  fs.writeFileSync(`${OUT}\\answer_wait.txt`, 'WAITING')
  for (let i=0;i<180;i++){
    await new Promise(r=>setTimeout(r,1000))
    const t = fs.readFileSync(`${OUT}\\answer_wait.txt`,'utf8').trim()
    if (t && t!=='WAITING') return t
  }
  throw new Error('no answer')
}

const run=async()=>{
  const b=await chromium.launch({headless:true})
  const ctx=await b.newContext({viewport:{width:1600,height:860}})
  const p=await ctx.newPage()
  const apiLogs=[]
  p.on('response',async r=>{ if(r.url().includes('unionBank/page')){ try{const j=await r.json();apiLogs.push(JSON.stringify(j).slice(0,400))}catch(e){} } })
  await p.goto(`${BASE}/#/login`,{waitUntil:'domcontentloaded'})
  await p.waitForSelector('.login-form',{timeout:30000})
  await p.waitForTimeout(2500)
  // screenshot the actual captcha element
  await p.locator('img.login-code-img').screenshot({ path: `${OUT}\\displayed_cap.png` })
  console.log('CAP_SAVED')
  const answer = await readAnswer()
  console.log('ANSWER=', answer)
  await p.locator('input[placeholder*="用户名"]').fill(USER)
  await p.locator('input[placeholder="请输入用户密码"]').fill(PASS)
  await p.locator('input[placeholder="请输入验证码"]').fill(String(answer))
  await p.locator('.login-button').click({ force:true })
  try {
    await p.waitForURL(u=>!u.hash.includes('/login'),{timeout:15000})
  } catch(e){
    // read error dialog
    const err = await p.locator('.el-message-box__message').first().innerText().catch(()=>'')
    console.log('LOGIN_FAIL_DIALOG=', err)
    await b.close(); process.exit(2)
  }
  console.log('LOGIN OK')

  await p.goto(`${BASE}/#/spfzjjg/zjjg/ACCOUNT_OPEN/account/add`,{waitUntil:'domcontentloaded'})
  await p.waitForTimeout(3000)
  await p.evaluate(()=>{
    const f=(vm)=>{if(!vm)return null;if(vm.showVisionOfBank)return vm;for(const c of vm.$children||[]){const r=f(c);if(r)return r}return null};
    const vm=f(document.querySelector('#app')?.__vue__); if(vm){vm.form.bankId=vm.form.bankId||'1';vm.showVisionOfBank()}
  })
  await p.waitForTimeout(4000)
  const dlg=p.locator('.zs-select-dialog').last()
  if(!(await dlg.count())){console.log('NO DIALOG');await b.close();return}

  const meas=(sel)=>dlg.evaluate((el)=>{
    const body=el.querySelector('.el-dialog__body'); const pag=el.querySelector('.pagination-container')
    const b=body.getBoundingClientRect(), pr=pag.getBoundingClientRect()
    return {bodySh:body.scrollHeight, bodyCh:body.clientHeight, pagTop:Math.round(pr.top), pagBottom:Math.round(pr.bottom), bodyTop:Math.round(b.top), bodyBottom:Math.round(b.bottom), pagInView: pr.top>=b.top-1 && pr.bottom<=b.bottom+1, dialogH:Math.round(el.getBoundingClientRect().height), pagText:(pag.innerText||'').replace(/\n/g,' ')}
  })
  console.log('BEFORE=',JSON.stringify(await meas()))
  await p.screenshot({path:`${OUT}\\verify_before.png`})

  // simulate the fix (add modifier + table fill height)
  await p.evaluate(()=>{
    const all=document.querySelectorAll('.zs-select-dialog'); const d=all[all.length-1]
    d.classList.add('zs-select-dialog--table-scroll')
    const t=d.querySelector('.el-table'); if(t){ t.style.height='100%' }
  })
  await p.waitForTimeout(800)
  console.log('AFTER=',JSON.stringify(await meas()))
  await p.screenshot({path:`${OUT}\\verify_after.png`})
  await b.close()
}
run().catch(e=>{console.log('ERR',e.message);process.exit(1)})
